def translate_html(source: str, locale: str) -> str:
    if locale not in LOCALES:
        return source
    index=LOCALES[locale]
    def text_node(match):
        raw=match.group(1)
        value=unescape(raw.strip())
        if value not in WORDS:return match.group(0)
        left=raw[:len(raw)-len(raw.lstrip())]
        right=raw[len(raw.rstrip()):]
        return '>'+left+escape(WORDS[value][index],quote=False)+right+'<'
    # Translate only HTML text nodes; never modify original JS or CSS.
    source=re.sub(r'>([^<>]+)<',text_node,source)
    def data_fr(match):
        value=unescape(match.group(1))
        return 'data-fr="'+escape(WORDS[value][index],quote=True)+'"' if value in WORDS else match.group(0)
    return re.sub(r'data-fr="([^"]*)"',data_fr,source)
